            const dialogRef = useRef(null);

            useEffect(() => {
                const dialog = dialogRef.current;
                if (isOpen) {
                    dialog.showModal();
                } else if (dialog.open) {
                    dialog.close();
                }
            }, [isOpen]);

            const handleClose = (e) => {
