        const { useState, useRef, useEffect } = React;

        const DeleteConfirmationDialog = ({ isOpen, onClose, onConfirm }) => {
            const dialogRef = useRef(null);

            useEffect(() => {
                const dialog = dialogRef.current;
                if (isOpen) {
                    dialog.showModal();
                } else if (dialog.open) {
                    dialog.close();
                }
            }, [isOpen]);

            const handleClose = (e) => {
                // Prevent default behavior if needed, but here we just sync state
                onClose();
            };

            const handleCancel = () => {
                dialogRef.current.close(); // This will trigger the onClose event
            };

            return (
