     <script type="text/babel">
         const { useState, useRef, useEffect } = React;

         const DeleteConfirmationDialog = ({ isOpen, onClose, onConfirm }) => {
             const dialogRef = useRef(null);

             useEffect(() => {
                 const dialog = dialogRef.current;
                 if (isOpen) {
                     dialog.showModal();
                 } else if (dialog.open) {
                     dialog.close();
                 }
             }, [isOpen]);

             const handleClose = (e) => {
                 // Prevent default behavior if needed, but here we just sync state
                 onClose();
             };

             const handleCancel = () => {
                 dialogRef.current.close(); // This will trigger the onClose event
             };

             return (
                 <dialog 
                     ref={dialogRef} 
                     onClose={handleClose}
                     aria-labelledby="dialog-title"
                     aria-describedby="dialog-description"
                 >
                     <div className="dialog-content">
                         <div className="dialog-header">
                             <h2 id="dialog-title" className="dialog-title">Delete Image?</h2>
                         </div>
                         <div className="dialog-body">
                             <p id="dialog-description">
                                 Are you sure you want to delete this image from your library? This action cannot be undone.
                             </p>
                         </div>
                         <div className="dialog-actions">
                             <button 
                                 type="button" 
                                 className="btn btn-secondary" 
                                 onClick={handleCancel}
                             >
                                 Cancel
                             </button>
                             <button 
                                 type="button" 
                                 className="btn btn-danger" 
                                 onClick={onConfirm}
                             >
                                 Delete
                             </button>
                         </div>
                     </div>
                 </dialog>
             );
         };

         const App = () => {
             const [isDialogOpen, setIsDialogOpen] = useState(false);
             const [isDeleted, setIsDeleted] = useState(false);

             const openDialog = () => setIsDialogOpen(true);
             const closeDialog = () => setIsDialogOpen(false);

             const handleConfirmDelete = () => {
                 setIsDeleted(true);
                 setIsDialogOpen(false);
                 // In a real app, you'd perform the deletion here.
             };

             if (isDeleted) {
                 return (
                     <main className="container">
                         <h1>Image Deleted</h1>
                         <p>The image has been successfully removed from your library.</p>
                         <button 
                             className="btn btn-secondary" 
                             onClick={() => setIsDeleted(false)}
                         >
                             Reset Demo
                         </button>
                     </main>
                 );
             }

             return (
                 <main className="container">
                     <h1>Image Preview</h1>
                     <img 
                         src="https://picsum.photos/seed/picsum/600/400" 
                         alt="A beautiful landscape" 
                         className="image-preview" 
                     />
                     <div>
                         <button 
                             className="trigger" 
                             onClick={openDialog}
                             aria-haspopup="dialog"
                         >
                             Delete Image
                         </button>
                     </div>

                     <DeleteConfirmationDialog 
                         isOpen={isDialogOpen} 
                         onClose={closeDialog} 
                         onConfirm={handleConfirmDelete} 
                     />
                 </main>
             );
         };

         const root = ReactDOM.createRoot(document.getElementById('root'));
         root.render(<App />);
     </script>
